mutation ReviewWarnings($input: DraftOrderInput!) {
  draftOrderCalculate(input: $input) {
    calculatedDraftOrder {
      warnings {

        ... on DraftOrderDiscountNotAppliedWarning {
          priceRule { title discountCodes(first: 1) { nodes { code } } }
        }
      }
    }
  }
}

